onference Centre',5,'Pennefather Ave, Harare, Zimbabwe',0.00,550.00,'Diplomatic Suite',11,11,'[\"WiFi\", \"Breakfast\", \"Gym\", \"Restaurant\", \"Conference Halls\", \"Shuttle\"]','Official venue diplomatic suites at Rainbow Towers, available on a bed and breakfast basis.',NULL,NULL,1,1,'2026-07-16 13:33:38','2026-07-16 13:33:38'),(8,'Kentucky Hotel',5,'24 St Patrick\'s Road',10.00,40.00,'Standard Room',10,10,NULL,'5 Star Hotel close to the Airport','','',0,0,'2026-07-16 14:06:02','2026-07-30 11:33:28');
