INSERT INTO `speakers` (`id`, `name`, `designation`, `church`, `country`, `bio`, `photo_url`, `keynote`, `display_order`, `created_at`, `updated_at`) VALUES (27,'BISHOP JEREMIAH MANGIZA','LOCAL ORGANISING COMMITTEE CHAIRPERSON','LOCAL ORGANISING COMMITTEE CHAIRPERSON','Zimbabwe','Bishop Mangiza joined the Methodist itinerant ministry in 1997 and was ordained on the 23rd of August 2003.<br><br><p><strong>He worked in  the following capacities:</strong></p><p><ul><li>2002 – 2011	Circuit Superintendent Minister&nbsp;</li><li>2012 – 2025	Schools Principal</li><li>2011 – 2014 	Connexional MCU Chair&nbsp;</li><li>2004 – 2009 	Connexional Candidates Secretary&nbsp;</li><li>2005 – 2009	Christian Care Regional Secretary&nbsp;</li></ul></p><p>Bishop Mangiza was appointed to be the Bishop of Harare East District in August 2025. He holds a Master of Arts Degree, a Bachelor of Arts Honours, and a Diploma in Religious Studies from the University of Zimbabwe. He also holds a Diploma in Theology from United Theological College, a Postgraduate Degree in Education from Great Zimbabwe University, a certificate in counselling from Connect, and a Postgraduate Certificate in Management from Corat Africa. Bishop Mangiza is married to Shupikai Future, and the union has been blessed with 4 children, 2 daughters-in-law, and 2 grandsons.&nbsp;</p><p><br></p>','/uploads/speakers/1786090312102-ce796410fbc1.jpg',0,1,'2026-08-07 08:04:39','2026-08-07 08:11:52'),(28,'REVD LIKHAI MOLIFE','GENERAL SECRETARY','THE METHODIST CHURCH IN ZIMBABWE','Zimbabwe','Revd Likhai Molife was born on 18 April 1969. He is married and is blessed with three children. Revd Molife joined the Methodist ministry in 1999 and has held many positions, including Circuit Minister, Circuit Superintendent, School Principal, and District Bishop. Currently, he is the General Secretary of the Methodist Church in Zimbabwe. Revd Molife holds a BA Honours) from the University of Zimbabwe.&nbsp;','/uploads/speakers/1786090390687-37ea3c406503.png',0,0,'2026-08-07 08:13:11','2026-08-07 08:13:11'),(29,'REV MUSI SIMON JACOB LOSABA','GENERAL SECRETARY OF THE METHODIST CHURCH OF SOUTHERN AFRICA','THE METHODIST CHURCH OF SOUTHERN AFRICA','South Africa','Married to Khahliso with three children and a grandson.<p><br><p>Musi is currently serving as the General Secretary of the Methodist Church of Southern Africa. This transnational Church works throughout six countries, including South Africa and other Member Countries of the MCSA, including Lesotho, Eswatini, Botswana, Mozambique, and Namibia.</p><p><br></p><p>Before being General Secretary, he served as the Director: Mission Unit of the Methodist Church of Southern Africa, 2018-2024 and also as Director: Ecumenical Affairs Unit of the Methodist Church of Southern Africa, 2015-2017.</p><p><br></p><p>2009 to 2014, he became the Bishop of the Grahamstown District, now known as William Kama District. Before serving in the above offices, Rev Losaba also served in several Circuits of the MCSA as Superintendent Minister and resident minister.&nbsp;&nbsp;</p><p><br></p><p><strong>Special gifts</strong>: Leadership and development of others, especially the young ministers. Preaching and teaching are also his passion.</p><p><br></p><p><strong>Hobbies:</strong> Reading and watching documentaries (especially on Church and politics), and sports.</p><p><br></p></p>','/uploads/speakers/1786090490538-5063245ec648.jpg',1,0,'2026-08-07 08:14:53','2026-08-07 08:14:53'),(30,'MOST REVD BANNIE E F MANGA','','METHODIST CHURCH THE GAMBIA','GAMBIA','The Most Revd. Bannie E. F. Manga celebrates his birthday on June 25, the day he also celebrates his ordination as a Methodist Presbyter.&nbsp;<p><br><p>He was baptised and confirmed a member of the Bethel Methodist Church, Stanley Street, Banjul. His confirmation text was 1 Timothy 4: 12 – Do not let anyone look down on you because you are young, but be an example of the believers in your speech, conduct, love, purity, and faith. This text has always mirrored his life and witness wherever he found himself.&nbsp;</p><p>Bishop Bannie holds a Master\'s degree in Applied Theological Studies from the University of Birmingham and a Bachelor of Divinity from Trinity Theological Seminary in Ghana. Bishop Bannie enjoys the honour of being the only Gambian minister to have served in most, if not all, ministerial portfolios of the Methodist Church in The Gambia.&nbsp;</p><p><br></p><p>He served as Circuit Minister, School Chaplain, Youth Minister, Assistant Synod Secretary, Synod Secretary, Assistant Secretary of Conference, Superintendent Minister, and Secretary of Conference. In February 2022, Bishop Bannie was consecrated as the fourth Presiding Bishop of The Methodist Church in The Gambia. He became the first indigenous minister since the Church became autonomous—Most Revd. Bannie is also privileged to serve in shaping and forming Christian Religious Educators at The Gambia College from September 2009 to 2022. He also participated in shaping minds at the University of The Gambia from 2016 to date, and he lectures at the Methodist Lay Preachers\' School. Being a people-centred person, Bannie is a pastoral counsellor, teacher, pastor, motivational speaker, and, in his words, \"a happy, jolly person\" who believes in maximising the potential and possibilities available to and for all.&nbsp;</p><p>His interests centre on watching football, debating current affairs, and helping others realise their potential.&nbsp;</p><p>Bannie is married to Jainaba, and the two are blessed with three children – JAINIE, JAINABA, AND JOE.</p><p><br></p></p>','/uploads/speakers/1786090575073-ed19f4eeacc0.jpg',0,0,'2026-08-07 08:16:16','2026-08-07 08:16:16'),(31,'RIGHT REVD. DR. BABATUNDE ABIODUN TAIWO JP, TFG, Fell. IMCON','','','','The Rt. Rev. Dr B. A. Taiwo was born 61 years ago into the Methodist family of Mr. &amp; Mrs Olumide Akinsola Taiwo at No 7 Wesley Street behind Wesley House of the Methodist Church Nigeria Headquarters in Lagos Island, L. G. Area of Lagos State. His grandfather was one of the pioneer missionaries of the Methodist Church Nigeria.&nbsp;<p>&nbsp;<p>His parents were successful teachers by profession. He is the 3rd of five in the family, and his dream and vision for the family is to uphold the good name of the Taiwo family.&nbsp;</p><p><br></p><p>As a brilliant lad, his pursuit of academic advancement took him to Christ Church Cathedral, Marina, Lagos, for his Primary education, Badagry Grammar School, Badagry, and Eko Boys\' High School, Mushin, Lagos, for his Secondary Education. He also attended Lagos State Staff Training School, Ikeja, and later the Citizenship and Leadership Training College, Apapa, Lagos, for his post-secondary education.</p><p>In 1985, he joined the itinerant Ministry of the Methodist Church, Nigeria, as a Ministerial Cadet under the then Very Rev. G. A. A. Bamgbose, the retired Bishop of Owo. He was commissioned as a deacon in 1986. He was trained at Trinity (Union) Theological College, Umuahia, now Abia State. After he graduated from the Theological College, he served for 3 years as a Chaplain to Most Rev. J. O. Obaba, former Archbishop of Lagos. He was ordained in 1991 into the full connexion of the Methodist Church as a priest.   There, he proceeded to the University of Calabar, Department of Philosophy and Religious Studies, for further studies for his first degree. Because of his quest for knowledge, he was immediately admitted to the University of Lagos for his postgraduate studies.&nbsp;&nbsp;</p><p><br></p><p>He holds Master\'s, M.Phil, and PhD Certificates in Philosophy from the University of Lagos (UNILAG), with a speciality in Logic and Metaphysics. He attended many seminars and conferences. As an erudite scholar, he is a celebrated guest speaker at national and international seminars, symposia, and conferences. He served at the Methodist Theological Institute, Sagamu, as a Lecturer/Registrar for two years, after which he was transferred to the Ibadan Diocese, Bodja Circuit, as a Presbyter (2001 – 2003). While at Bodija, he also served as a Lecturer to Degree students of Immanuel College of Theology, Ibadan.</p><p>The Archbishop of Ibadan, Most Rev. Dr E. S. Ogunyemi, graciously assigned him the responsibility of coordinating the hosting of the 2002 Conference of the Methodist Church Nigeria as the Presbyter of Bodja Circuit in the Diocese of Ibadan. This conference was adjudged the neatest.&nbsp;&nbsp;</p><p>Also, while in Ibadan, many achievements were made during his tenure, mostly in spiritual upliftment. The leadership quality of Most Rev. Dr &amp; Mrs. E. S. Ogunyemi is highly commended in the Ministry of Bishop B. A. Taiwo.</p><p>In October 2003, he was transferred to the Cathedral of Unity as a Presbyter of the Wuse Circuit.&nbsp;&nbsp;</p><p>While in Abuja, many remarkable achievements were made; notable among them were spiritual upliftment. In this area, many new churches were planted, including Methodist Church Lugbe, Methodist Church Kuje (with a Manse for the Priest in charge), Methodist Church Chika, and Methodist Church Sabon Lugbe/MCN Pyakasa. Because of this rapid expansion, the Cathedral Circuit was created from the Wuse Circuit, and he became the pioneer Presbyter/Administrator of the Cathedral Circuit.&nbsp;&nbsp;</p><p>Methodist Nursery and Primary School was started and built. His Eminence, Dr Sunday Mbang, on August 26, 2005, commissioned the school on a large, vast piece of land in Abuja. This school is one of the investments Rt. Rev. B. A. Taiwo left for the Cathedral of Unity.</p><p>&nbsp;The impact of Bishop Taiwo will ever remain fresh in the minds of members of the Methodist Cathedral of Unity, Wuse Zone 3, Abuja, for his numerous achievements. It was during his tenure that the Church began to enjoy a well for potable drinking water. He also increased the number of buses by purchasing a new 18-seater Toyota bus (fully air-conditioned). Also worth noting is his establishment of a formidable Youth Fellowship with an office and a set of Computers to enable the youths to become self-reliant, self-existing, and self-propagating.&nbsp;</p><p>His impact is also being felt in FCT in general, and in 2006, he was appointed Federal Government Delegate, leading the FCT Pilgrims to Jerusalem. He is also an Executive member of the FCT Christian Association of Nigeria.</p><p>&nbsp; Bishop Taiwo served as the Secretary on the \"Conference ad hoc Committee to review existing Committee\" towards the Repositioning of the Church, under the Chairmanship of Archbishop Rojas Uwadi.&nbsp;</p><p>The Rt. Rev. Dr B. A. Taiwo is one of the most remarkable and effective exponents of evangelism in his generation. He is a man of God, skilled in the art of teaching, preaching and administration, applying discipline. He is a sensible, practical, biblical, and theological scholar. You will find the intensely personal familial feelings that exist between the Church members and Rt. Rev. Dr Taiwo, wherever he has served.</p><p>An ever-smiling gentleman who loves neatness and hates dirt. Kind, firm and hardworking, a Pastor and friend of all. His Ministry is strongly supported by his lovely, caring, and beautiful wife, who is equally an Evangelist and a woman leader.</p><p>He was elected Bishop of Remo, later posted to serve in Edo Delta, Umuahia West, and Elekuro, and is currently the Secretary of the Conference, Methodist Church Nigeria.&nbsp;</p><p><br></p><p><strong>AWARDS</strong></p><p>1.	Doctor of Theology at Wesley University, Ondo</p><p>2.	Doctor and Fellow of the Institute of Leadership, Manpower and Management Development</p><p>3.	Fellow, Philosophy Association of Nigeria</p><p>4.	Fellow, Institute of Management Consultants</p><p>5.	The faithful of God by the Archdiocese of Aba</p><p>The Rt. Revd. Dr B. A. Taiwo is married to his beautiful and charming wife, Asiwaju Esther Abimbola Taiwo, an Educationist/Managing Director of Esther Glamour Enterprises, and is blessed with 3 lovely Children.</p><p><br></p></p>','/uploads/speakers/1786090652822-8b189d4b06e4.jpg',0,0,'2026-08-07 08:17:33','2026-08-07 08:17:33'),(32,'REVD PUMLA NZIMANDE','PRESIDING BISHOP – METHODIST CHURCH OF SOUTHERN AFRICA','METHODIST CHURCH OF SOUTHERN AFRICA','SOUTH AFRICA','Revd. Pumla Nzimande is an ordained minister of the Methodist Church of Southern Africa (MCSA), currently serving as the Presiding Bishop. She has a passion for education, empowerment, and spiritual formation and has a proven track record in leadership, policy development, gender equality, and women\'s advocacy.<p><br><p>With over 20 years of ministerial experience, Rev Nzimande is known for her leadership skills, creativity in problem-solving, and team building, as well as the excellence she lives by. Rev Nzimande holds a Master\'s Degree in Systematic Theology and Ethics from the University of South Africa.&nbsp;</p><p><br></p><p>An energetic and proactive Christian leader, Rev Nzimande is committed to equality, justice, integrity, congruence, accountability, and discipline.&nbsp;</p><p><br></p><p>Born on 01/09/1982 in Durban, South Africa, the fourth of five children, Rev Nzimande grew up in iNtuzuma Township and later on in Queensburgh, Durban, South Africa. Her call to Ministry developed in the late 90s; she heeded the call and offered herself to the Ministry in 2003.  She has worked in several circuits within the MCSA, including the Victoria Road Circuit, Pimville Circuit, St Stithians College, Moraleta Circuit  (Eersterust), and was the Education Mission and Ministry Unity (EMMU) Co-ordinator for Lay Ministry and the EMMU Director before taking up the office of Presiding Bishop. She has served in various leadership positions in the MCSA across the youth and education structures.&nbsp;</p><p>She is a firm believer in gender equality, incarnational Ministry, and ethical and transformational leadership.</p><p><br></p></p>','/uploads/speakers/1786090749186-7b01049e6732.jpg',0,0,'2026-08-07 08:19:10','2026-08-07 08:19:10'),(33,'REV. PROF. PETER MAGETO MAIKO','VICE CHANCELLOR- AFRICA UNIVERSITY','AFRICA UNIVERSITY','ZIMBABWE','Personal Vision &amp; Mission: *Advancing Ethical Leadership and Pan-African Higher Education.*&nbsp;&nbsp;<p><br><p>Rev. Prof. Peter Mageto Maiko is a distinguished academic, theologian, and higher education leader whose career has been dedicated to advancing ethical leadership, institutional excellence, and transformative education across Africa.&nbsp;</p><p>&nbsp;</p><p>As Vice Chancellor of Africa University in Zimbabwe, he leads one of the continent\'s most influential institutions, serving students from across Africa while advancing a vision of higher education that cultivates leadership, innovation, and lasting social impact. In recognition of his exemplary leadership in higher education, the Government of Zimbabwe appointed him to the Council of Zimbabwe Council for Higher Education, the statutory body responsible for regulating, assuring quality, and safeguarding standards across Zimbabwe\'s higher education sector. He also serves as a member of the Kisii University Council, Kenya, reflecting the high regard in which his leadership, governance expertise, and strategic vision are held across the region.&nbsp;</p><p>&nbsp;</p><p>Born in Nyamira County, Kenya, Rev. Prof. Mageto began his educational journey at  Matierio Primary School before attending Kebabe Mixed Secondary School. He holds a Bachelor of Divinity from St. Paul\'s United Theological College, a Master of Theological Studies, and a PhD in Theological Ethics from Garrett-Evangelical Theological Seminary. He earned a postgraduate certificate in African Studies from Northwestern University and completed the Stanford GSB LEAD Certificate, strengthening his expertise in leadership, governance, and institutional transformation. His academic and professional journey spans more than three decades of teaching, research, Ministry, and university leadership.&nbsp;</p><p>&nbsp;Before his appointment at Africa University, Rev. Prof. Mageto served as Vice  Chancellor of the University of Kigali, Acting Vice Chancellor and Deputy Vice Chancellor (Academic and Student Affairs) at Kenya Methodist University, and Professor at Daystar University. His scholarship and thought leadership have focused on theological ethics, leadership, education, peacebuilding, reconciliation, and social responsibility, reflecting a lifelong commitment to human dignity, ethical governance, and societal transformation.&nbsp;</p><p>&nbsp;</p><p>A passionate advocate for Pan-African collaboration, Rev. Prof. Mageto has consistently championed higher education as a catalyst for sustainable development, responsible leadership, and social progress. His leadership philosophy is grounded in integrity, accountability, inclusivity, and servant leadership, emphasising the development of graduates who combine professional excellence with unwavering ethical responsibility.&nbsp;</p><p>&nbsp;Rev. Prof. Mageto is married to Dr. Irene G. Mageto and is blessed with two children. Through his contributions to higher education, ethical governance, and leadership development, Rev. Prof. Mageto is shaping a generation of principled leaders equipped to address Africa\'s most pressing challenges. His enduring legacy is redefining African universities as engines of innovation, ethical leadership, knowledge creation, and societal transformation, inspiring a future in which education remains one of the continent\'s greatest forces for progress, human flourishing, and Pan-African advancement.&nbsp;</p><p><br></p></p>','/uploads/speakers/1786090823113-c764d6ff50d2.jpg',1,0,'2026-08-07 08:20:26','2026-08-07 08:20:26'),(34,'REVD DR REYNALDO FERREIRA LEÃO NETO','GENERAL SECRETARY- WORLD METHODIST COUNCIL','WORLD METHODIST COUNCIL','','Revd Dr Reynaldo Ferreira Leão Neto, known as Léo, is the General Secretary of the World Methodist Council since August 2024. He previously served the Methodist Church in Britain as a member of the Conference Office and the Connexional Team for 5 years. From 2011-2019, he was the Superintendent minister at Harlesden Circuit in London. Before that, he served at Hinde Street Church of the West London Mission, the nearest Methodist Church to Charles Wesley\'s place of rest, in Marylebone. From 1996 to 1999, he was a mission partner in reverse, serving with the Grassroots Ecumenical Programme, engaging in community mission and interfaith relations. In his previous existence in Brazil, he was a lay pastor on the outskirts of São Paulo and Rio de Janeiro, ministering to very poor communities. He was the local organiser for the WCC-UNCED meeting in Rio, Eco92. Leo is married with two grown-up children.','/uploads/speakers/1786090904175-49c13d63783d.jpg',0,0,'2026-08-07 08:21:46','2026-08-07 08:21:46'),(35,'ELSIE MACAULEY ','AMC YOUTH CHAIRPERSON','AFRICA METHODIST COUNCIL','GHANA','Elsie is a Youth and Community Development enthusiast, a Sexual and Reproductive Health and Rights (SRHR) Advocate and Mentor, with over a decade of experience in youth work and a bachelor\'s degree in management from the University of The Gambia.&nbsp;<p><br><p>She is a Continental youth leader in the Africa Alliance of YMCA\'s Leadership Programme and the S2C Ambassador Programme. She also doubles as a Global YMCA Change Agent and African Ambassador within the World Movement Youth Programme.</p><p>She is committed to the development of youth, especially vulnerable young people, in support of the African Renaissance. A trainer and an advocate on peace and security, focusing on the prevention of irregular migration and the reintegration of migrants into society.</p><p>Elsie is the Co-founder and President of the Young Advocates for Sexuality, Sexual Health and Sexual Rights (YASSS-GAMBIA), an organisation that strengthens young people\'s access to Sexual and Reproductive Health and Rights (SRHR), most especially marginalised groups in The Gambia, such as Persons with Disabilities (PWDs) and People Living with HIV (PLHIV).</p><p>She is committed to ensuring that young people in and out of school are free from all forms of violence, most especially women and girls and that they have equal access to their reproductive rights.</p><p>Her work and skills entail communication, policy engagement, community engagement, advocacy and youth development.&nbsp;</p><p>Elsie is passionate about reaching in- and out-of-school adolescents &amp; young adults through comprehensive sexuality education (CSE) to enable them to adopt positive sexual behaviours and strengthen gender equality. Therefore, equipping them with the right knowledge, skills, attitudes and values to make informed decisions about their total well-being individually and in relationships.</p><p>Elsie currently serves as the Youth Coordinator of the Methodist Church The Gambia, where she leads the development of the Youth Ministry.</p><p><br></p></p>','/uploads/speakers/1786091011487-90794a853c9a.jpg',0,0,'2026-08-07 08:23:32','2026-08-07 08:23:32'),(36,'BISHOP IVAN MANUEL ABRAHAMS','IMMEDIATE PAST WORLD METHODIST COUNCIL GENERAL SECRETARY','','','Bishop Ivan M. Abrahams, Immediate Past General Secretary of the World Methodist Council, served in the office from 2011 to 2024.   He has been involved with the World Methodist Council since 1986, serving as Chair of its Social and International Affairs Committee and numerous other functions.&nbsp;&nbsp;<p><br></p><p>His background. His theology has been influenced by the experiences encountered while ministering in the Cape Flats (Western Cape, South Africa). Most of his ministry was shaped by the anvil of the struggle against the notorious apartheid regime.&nbsp;</p><p><br></p><p>Education: Ivan did his Senior Secondary education at Heathfield High School in the Western Cape, where he matriculated. He held several leadership positions - Head Boy, President of the SRC, and captain of the rugby and athletic teams.&nbsp;</p><p><br></p><p>After his call to ministry, he trained at the Federal Theological Seminary. He did his BTh (Rhodes University), BA Hons (University of Cape Town), Postgraduate Certificate of Special Studies, CSS (Berkeley, US),  MTh (UKZN) – Summa Cum Laude on the topic \"Towards a Theology of Labour: A Theo-historical Enquiry of the Interface between the English-speaking Churches and Labour (1985-1995)</p><p><br></p><p>His Ministry &amp; Mission - (Work Experience before becoming the General Secretary of the WMC)</p><p><br></p><p><ul><li>General Secretary -World Methodist Council 2011-2024</li><li>Presiding Bishop of the Methodist Church of Southern Africa (2003 – 2012), one of the largest Christian denominations in a region that spans six countries.&nbsp;</li><li>Bishop of Namibia (1992 – 1996).&nbsp;</li><li>Director of the Mission Unit (1997 – 2011). He was responsible for church growth, spirituality, justice, and service portfolios in six Southern African countries.&nbsp;</li><li>Superintendent Minister of various Circuits throughout South Africa.</li><li>(local) Minister in various congregations (Mitchell\'s Plain, Kalksteenfontein, Verulam, Bloemfontein)</li><li>Participated in numerous institutional structures, such as:</li><li>Chairperson of Ecumenical Service for Social and Economic Transformation (ESSET)</li><li>Member of the Executive Committee of the South African Council of Churches&nbsp;</li><li>(led SACC delegation to Zimbabwe)</li><li>Chairperson of the South African Church Leaders Forum. (Led a delegation of church leaders on a pastoral visit to Zimbabwe. This culminated in the landmark call of the South African Council of Churches for new action to end the suffering of the people of Zimbabwe. Secondly, he led a delegation to Rwanda at the request of the then-South African Ambassador.</li><li>Chairperson of the National Religious Leaders Forum</li><li>He is serving as a member of the Executive Committee of the World Council of Churches.</li><li>Served on the State Information Technology Agency (SITA) tender board</li><li>Member of the Edendale (Gauteng) Hospital Board</li><li>Chairperson of the Detainees Parents  Support Committee (in the Free State: Bloemfontein)</li></ul></p><p><br></p><p>He is also well known throughout the world, having served in various capacities and invitations to give addresses, sermons, Conferences, Seminars, and Workshops:&nbsp;</p><p><br></p><p>Africa (South Africa, Zimbabwe, Rwanda, the Democratic Republic of the Congo, Palestine, Nigeria, Mozambique, Angola)</p><p><ul><li>Rwanda: part of a Southern Africa delegation to facilitate reconciliation on the invitation of the South African Ambassador.</li><li>Democratic Republic of Congo: part of a delegation to facilitate peace and reconciliation and a courtesy visit to Ambassador Molefi Tsele.</li><li>Nigeria, Kenya, The Gambia, Ghana, Kenya, Swaziland:  Part of the ministry of oversight as General Secretary and preaching and meeting political heads in the respective countries</li><li>Mozambique: worked with Development Agencies.</li><li>Angola: Facilitating the integration of the Methodists into the MCSA Conference</li></ul></p><p><br></p><p>Middle East (Palestine, Jordan, Israel, the Gaza Strip) - The purpose was to seek resolution for the conflict in the Middle East.</p><p><br></p><p><strong>Asia (Korea, India, Thailand)</strong></p><p>Facilitated numerous meetings to seek resolution for peace in the Korean Peninsula; presented several addresses at Conferences on Peace and Unity; In India, presented papers on the 70th Independence Anniversary celebrations.&nbsp;</p><p><br></p><p><strong>Europe (UK, Germany, Sweden, Italy, Albania, Norway, Poland)</strong></p><p>UK: Secretaries of World Communion Meeting; 	British Methodist Conference: Addressing the Presbyter Session; Methodist Central European Conference: Addressing Conference on MIGRATION; Preparation for WMC 2021 Conference in Sweden; Italy:  La Sapienza Seminar &amp; Launch of WMC Office;  Tirana, Albania: Global Christian Forum Conference; Switzerland: Methodist Council Peace Award Ceremony; Germany: Conference Addresses; Norway: Conferences and preaching; Sweden: Conferences and preaching; Poland: Conferences and preaching</p><p><br></p><p><strong>Americas (USA, Canada)</strong></p><p>(Orlando USA: Free Methodist Conference - Addressing (4,500) delegates on the theme: GOING GLOBAL in the Wesleyan Tradition; Houston, Texas USA: WMC Steering Committee Meeting; Atlanta: Methodist Council Peace Award Ceremony, Martin Luther King Jr. Lecture&nbsp;</p><p><br></p><p><strong>Latin America (Mexico, Brazil, Costa Rica, Colombia)</strong></p><p>Brazil:  Attended and addressed Conferences and Preached; Colombia: seeking to bring about peace; Mexico:  Conferences and meetings with Government Officials and Civil Society Organisations.</p><p>Jamaica: Chair of the drafting Committee of the WCC – Just Peace&nbsp;</p><p><br></p><p><strong>Australasia (Samoa, Fiji, Australia)</strong></p><p>Fiji: Part of the team to seek resolution (negotiations) between Church and society; Australia: Facilitating the WMC Peace Award Ceremony and engaging with civil society.</p><p><br></p><p>Some of his achievements – within and outside the faith community</p><p><br></p><p><strong>Among his notable achievements as a Church Leader&nbsp;</strong></p><p>the successful creation and completion of Seth Mokitimi Methodist Seminary in Pietermaritzburg, South Africa.&nbsp;</p><p>Creating an enabling environment for women clergy to fill a leadership position in the MCSA.</p><p>In 2013, Abrahams delivered a sermon at the funeral of Nelson Mandela in Johannesburg, South Africa.&nbsp;</p><p>He is active in various forums, including the All-Africa Conference of Churches and the Central Committee of the World Council of Churches, including being Co-Chairman of the Social and International Affairs Committee of the WMC.</p><p>Testified in the Congressional Hearing in the USA on Children and Detention (1985)</p><p>Received the Global Aids Award – United Methodist Church</p><p>Honoured by the community of Bloemfontein by naming an Educare centre as the Ivan Abrahams Educare Centre in Bloemfontein, Free State (South Africa)</p><p>He was honoured by Methodists in Luanda, Angola, by having a church named after him.</p><p><br></p>','/uploads/speakers/1786091209416-78d5aa8f07a3.jpg',0,0,'2026-08-07 08:26:50','2026-08-07 08:26:50'),(37,'REVD DR. MUKOMUNENE MUTHURI','MODERATATOR','METHODIST CHURCH IN KENYA','KENYA','Revd Dr Mukomunene Muthuri is a Circuit Minister in the Methodist Church in Kenya. She currently serves at Lavington United Church, Lavington Circuit of Nairobi Synod as the Youth and Teens Minister. Previously, she served Children and Youth at Langata, Maziwa, and Kariokor Circuits, all of Nairobi Synod. She was also Synod Coordinator for both Children and Youth, an administrative role in the Bishop\'s office.<p>She is passionate about discipling the Next Generation, that is, Children and Youth, and she desires to see both groups get to know, love and serve the LORD as they answer their calling in ministry to the Church and community. Ecumenically, she serves with CHILDNET Tuamke and NAYNET Kenya, in the training of Sunday school teachers and youth workers serving in the city of Nairobi and beyond.</p><p>She serves the continent of Africa in the Executive of the Africa Methodist Council Youth Movement as Chaplain.</p><p>Her academic credentials are as follows: - Bachelor of Divinity at St Paul\'s University, Limuru, Master of Theology at MF Norwegian School of Theology, Oslo, and Doctor of Ministry from Wesley Theological Seminary, Washington DC.</p><p><br></p>','/uploads/speakers/1786091299541-27f638e6e1f9.jpg',0,0,'2026-08-07 08:28:21','2026-08-07 08:28:21'),(38,'REVD. DR. NOMTHANDAZO PURITY MALINGA','AFRICA METHODIST COUNCIL WOMEN\'S MOVEMENT CHAIRPERSON','AFRICA METHODIST COUNCIL ','GHANA','Rev Purity was born and raised at IXOPO – KwaZulu Natal, South Africa. After matriculation, she was trained and qualified as a teacher. She taught for 5 years. She then responded to the call to the ministry of Word and Sacrament in 1981 and was accepted by the Methodist Church of Southern Africa Conference of the same year. She did her theological Training at Federal Theological Seminary and obtained her Diploma in Theology with Greek, with Distinction. After ordination in 1988, she received a scholarship to further her studies, and she obtained her Master of Divinity Degree from Harvard University (USA) in 1992.<p>Rev Purity has vast experience in teaching, ministry, and leadership in the Methodist Church and in the Ecumenical bodies. In 2000 -2008 she led as a District Bishop in the Natal Coastal District - the first woman to occupy this position in the history of the MCSA. In 2019 she was elected Presiding Bishop of the MCSA again, the first woman to occupy this office. She retired from the office and from active ministry at the end of 2023. Rev Purity is an accomplished academic who has formed Theology students ecumenically. She is a promoter of inclusion and gender equality within the Church. In recognition of her contribution to the Church and society, she has been honoured by the University of South Africa (UNISA) with an honorary degree of Doctor of Philosophy in Theology.</p><p>In 2022, she accepted to contribute to the Africa Methodist Council by leading its women\'s wing known as the Women Movement, as chair of the Executive Committee.</p><p><br></p>','/uploads/speakers/1786091594833-3154dfdfeb62.jpg',0,0,'2026-08-07 08:33:16','2026-08-07 08:33:16'),(39,'MS BONGINKOSI MOYO-BANGO','COMMUNICATION COORDINATING SECRETARY','METHODIST CHURCH OF SOUTHERN AFRICA','SOUTH AFRICA','Bongie Moyo-Bango is a South Africa-based safe spaces facilitator and communications professional. She has a passion for leadership and human development, especially for young women and girls, and, as such, co-facilitates annual leadership camps focused on EQ and SQ, as well as CSE/SRHR. She holds a Master\'s degree in Peace and Governance and has had further Training in Responding to Conflict, Conflict Transformation and Mediation. The bulk of her work has been within the&nbsp;<p>ecumenical space, including the South African Council of Churches (SACC) and other councils within Southern Africa under FOCCISA and the World Council of Churches (WCC). On a regional level, she is an executive of the Africa Methodist Council, a regional ecumenical body. She has extensive knowledge of gender programming and programme design. She has facilitated several high-profile strategic planning sessions, including those for the Nelson Mandela Museum in Mthatha, South Africa (2019), and the Gauteng Department of Community Safety, South Africa (2018).  Ms Moyo-Bango has over 16 years of experience in communications, copywriting, and editing and 20 years of pan-African experience in human rights research and capacity building; safe spaces facilitation and training; gender programming, SRHR, strategic planning; leadership; advocacy; communication skills; HIV and AIDS. She has published several Contextual Bible Studies, human rights handbooks and toolkits, and Advocacy Briefs on SRHR for religious leaders in Southern Africa. A social activist, she has facilitated high-level meetings across Anglophone Africa for the World Council of Churches, Faith to Action Network, Amplify Change, INERELA+, ACT Ubumbano, Gender Links, and others. She is a Doctoral candidate at the University of Johannesburg</p><p><br></p>','/uploads/speakers/1786091792142-23b9055204e7.jpg',0,0,'2026-08-07 08:36:32','2026-08-07 08:36:32'),(40,'BISHOP SAMUEL KAYINAMURA ','ACTING VICE PRESIDENT OF EAST AFRICA','FREE METHODIST CHURCH IN RWANDA','RWANDA','Bishop Samuel Kayinamura serves as the leader of the Free Methodist Church in Rwanda. Samuel has experience in different services as a teacher, inspector of schools, inspector of labor, pastor and church leader.&nbsp;<p><br></p><p>He is a member of religious and institutional boards such as the Protestant Council of Rwanda, where he serves as the President. He also serves as the President of the Free Methodist World Conference. He is a Legal Representative of Kibogora Polytechnic and Deputy Legal Representative of the Bible Society of Rwanda, Protestant Institute of Arts and Social Sciences, now Protestant University of Rwanda. He is the deputy chair of the Rwanda Interreligious Council. Bishop Samuel holds a bachelor\'s degree in theology from the Faculty of Protestant Theology of Butare and a Master\'s degree in Conflict Resolution and Peace Studies from the University of KwaZulu Natal/ South Africa.&nbsp;</p><p><br></p><p>He is married and is blessed with 5 children, 3 sons and 2 daughters and 1 granddaughter.&nbsp;</p><p><br></p>','/uploads/speakers/1786091888278-311eed548d54.jpg',0,0,'2026-08-07 08:38:09','2026-08-07 08:38:09'),(41,'BISHOP  GEORGE T. MAWIRE','VICE PRESIDENT, SOUTHERN REGION','METHODIST CHURCH IN ZIMBABWE','ZIMBABWE','Bishop. G T. Mawire was born on October 6 1966, in Gutu District, Masvingo Province, in Zimbabwe. He hails from a family with a Clerical and Religious background. Revd. G.T. Mawire did his Primary and Secondary Education at Nyamandi Schools in Gutu and Waddilove Methodist Church in Zimbabwe High School in Marondera. He is married to Mrs. Pelagia Mawire and is blessed with two children, a son and a daughter. He was called to the Ministry in 1987, went to the United Theological College in 1989, and completed his Training in 1992. He was ordained in 1994. During his tenure as a minister, he served in various positions, including Circuit Minister, Circuit Superintendent, District Bishop, and Chaplain to the MCZ Fellowship in the UK, becoming the first Chaplain to establish the UK Fellowship. He also served as the Presiding Bishop of the Methodist Church in Zimbabwe from December 2021 to November 2025. Bishop Mawire is a holder of a Diploma in Theology, a Diploma in Church Administration, a Bachelor of Human Resource Management with the Zimbabwe Open University and a Master of Human Resource Development with Middlesex University, London. Bishop G.T. Mawire is known for his simplicity, listening skills, and accommodating nature. He is currently serving as the Principal of Waddilove Institute.&nbsp;','/uploads/speakers/1786091960662-d7d4731827b9.jpg',0,0,'2026-08-07 08:39:22','2026-08-07 08:39:22'),(42,'REVD GODSON DOGBÉDA TÉYI LAWSON KPAVUVU','VICE PRESIDENT FRANCO-PHONE WEST AFRICA AND THE PRESIDING BISHOP OF METHODIST CHURCH TOGO','METHODIST CHURCH TOGO','TOGO','Revd Godson Dogbéda Téyi LAWSON KPAVUVU is the Presiding Bishop of the Methodist Church Togo. He holds a Postgraduate Diploma (DEA) in Sociology from the University of Lomé and a Master\'s degree in Theology from the Faculty of Protestant Theology in Yaoundé, Cameroon.&nbsp;<p>Apart from sociology and theology, Godson has also done rich and varied Training such as: -   The Timeless Message for the New Millennium\" at Candler School of Theology of Emory University - Atlanta (USA); - Fight against the proliferation of small arms in West Africa with the Norwegian Initiative on Small Arms Trade - Oslo- Norway; -  Design and management of development projects with OIC International Abidjan - R.C.I; -  Conflict Management and Peacekeeping with the South African Council of Churches (SACC), Khotso House, Johannesburg, South Africa.</p><p>&nbsp;These various qualifications have enabled him to practice church diplomacy in conflict situations in the world, particularly in Africa and to hold high positions within the Methodist Church of Togo, such as Executive Director of the Methodist Community Development Program, Director of Methodist Education, Director of the Youth Department, Chairman of the District, General Secretary and now the Presiding Bishop. Godson has taken leading responsibilities in important national and international groups such as :- Secretary General of the Council of Churches in Togo ; Member of the Board of Directors of the Alliance Biblique du Togo ; West Africa Coordinator of the Youth Department of the All Africa Conference of Churches (AACC),  Member of the Board of Directors of the Réseau Ecole Développement (RED) Project, Abidjan-Côte d\'Ivoire ; Acting General Secretary of Fellowship of Councils and Churches in West Africa (FECCIWA),  Vice President of West African Network of Peace Building (WANEP International),  Assistant to the Southern Africa Office of the American Friends Service Committee of the Quaker International Affairs Program in Johannesburg, Kotso House - South Africa ;  Secretary of the National Advisory Council of PLAN INTERNATIONAL Togo ;  Monitoring and Evaluation Programs Officer at the Ecumenical Accompaniment Project of the Churches of Togo (PAOET) ; Member of the working group on Peace in Africa of the World Council of Churches Geneva – Switzerland ; Chair of the International Reference Group of the World Council of Churches Ecumenical HIV and AIDS Initiatives and Advocacy Programme, WCC-EHAIA, Geneva,  Co-Chair of Africa REACH Leadership Council, an African-led, African-focused effort that aims at an Africa with children and youth free from AIDS, led by the  former First lady of Namibia Her Excellency Mrs. Monica GEINGOS. Rev Godson is committed to influencing African political and cultural structures and generational leadership to accelerate continental momentum and catalyse a new action agenda in ending AIDS among children and youth in Africa. He is currently the Vice President/Chairman of the West Africa Francophone Region.</p><p><br></p>','/uploads/speakers/1786092015272-9b1676b4992e.jpg',0,0,'2026-08-07 08:40:15','2026-08-07 08:40:15'),(43,'HIS EMINENCE, DR. OLIVER ALI ABA JP','VICE PRESIDENT ANGLOPHONE WEST AFRICA AND PRELATE METHODIST CHURCH NIGERIA','METHODIST CHURCH NIGERIA','NIGERIA','His Eminence, Dr Oliver Ali Aba JP, the current Prelate of the Methodist Church Nigeria and Vice President of the Africa Methodist Council, is a distinguished leader with an illustrious career in the Church, marked by unwavering commitment and notable achievements. He was born on May 27, 1960, to the family of the late Mr. /Mrs. Audu Aba, both of Ogbadibo Local Government Area of Benue State, Nigeria. His upbringing laid the foundation for his values, fostering a sense of community and belonging that resonates in his leadership approach. Prelate Aba has held various roles within the Methodist Church Nigeria, demonstrating exceptional leadership and a profound dedication to the Church\'s structural and spiritual development. His leadership style is marked by a strategic focus on both the Church\'s physical and spiritual development.<p>His Eminence, Dr. Oliver Aba\'s educational journey reflects a steadfast commitment to academic and theological excellence. He commenced his formal education at L.G.E.A Primary School in Benue State, graduating in 1977 with the First School Leaving Certificate (FSLC). He continued at Lagos Secondary Commercial Academy from 1977 to 1980, and then moved to Government College, Benue State, where he successfully sat the Senior Secondary Certificate Examination (S.S.C.E.) in 1982. In his deep-rooted passion to serve God, he embarked on a theological journey at St. Augustine Major Seminary, Jos, from 1983 to 1986. During this time, he immersed himself in the study of Philosophy, laying a strong foundation for his future role as a spiritual leader. His theological pursuits continued at Immanuel College of Theology, Ibadan, where he obtained a Diploma in Theology from 1987 to 1990. Eager to deepen his understanding of Christian Religion Studies, he enrolled at the prestigious University of Ibadan, earning a Bachelor of Arts degree in Christian Religion Studies between 1990 and 1992. Demonstrating a commitment to scholarly advancement, Prelate Aba returned to the University of Ibadan between 1997 and 1998, where he obtained a Master of Arts in Church History. This academic achievement stands as a testament to his firm dedication to intellectual development and his desire to equip himself with the knowledge necessary to fulfil his divine calling.&nbsp;</p><p><br></p><p>Prelate Aba\'s journey in Ministry began as a Priest in 1993, and he steadily rose through the ranks, serving in various capacities, including as the Prelate\'s Chaplain and Lecturer at the Methodist Theological Institute, Sagamu. Notably, his election as Bishop in 2002 and subsequent translation to various Dioceses reflect the trust and confidence placed in his leadership abilities. In 2014, he became the Archbishop of Benue, leading significant structural developments within the archdiocese. His strategic vision and commitment to excellence are evident in the construction of vital infrastructure, including the archbishop\'s duplex, the Prelate\'s guest house, and a standard Chapel, all of which advance the Church\'s mission. Dr Oliver Ali Aba made history in 2022 by becoming the first Prelate from Northern Nigeria since 1842. His election following a keenly contested electoral college underscores his leadership prowess and the recognition of his exceptional contributions to the Methodist Church.</p><p><br></p><p>As Chairman of the Methodist Board of Theological College since 2012, he has played a pivotal role in shaping the theological education landscape. His involvement with the Benue Pilgrimage Board and his leadership positions in the Christian Council of Nigeria (CCN) and the Christian Association of Nigeria (CAN) further attest to his influence in ecumenical matters.</p><p><br></p><p>Prelate Aba is not only a respected religious leader but also a family man. Happily married to Deaconess Maria Aba, their union has been blessed with children, reflecting a balance between personal and professional responsibilities.&nbsp;</p><p><br></p>','/uploads/speakers/1786092225660-8f23fe207e2a.jpg',0,0,'2026-08-07 08:41:21','2026-08-07 08:43:46'),(44,'VERY REVD. ANTHONY KWAMENA COBBAH','HONORARY TREASURER','AFRICA METHODIST COUNCIL','GHANA','The Honorary Treasurer of AMC is the Immediate Past General Director of Finance and Development of the Methodist Church Ghana Conference.<p>The AMC appointed him the Honorary Treasurer in the early stages of the Council\'s formation. The Council renewed his mandate for four years at the second Quadrennial Conference, held in Cotonou, Benin, from 7 to 12 March 2023.</p><p><br></p><p><strong>Educational Background</strong></p><p>He holds an MBA (Finance Option) from the University of Manchester and a Diploma in Theology from Trinity Theological Seminary, Accra, Ghana.</p><p>Courses Attended</p><p><ul><li>USAID Financial Management Training in Nairobi, Kenya, and Johannesburg, South Africa.</li><li>Price Waterhouse Coopers Financial Management Training in Accra-Ghana</li><li>Strategic Management Course at GIMPA -Accra, Ghana.</li><li>International Purchasing Workshop Course Sponsored by the World Bank in Accra, Ghana</li><li>Presentation Skills by the British Council- Accra</li><li>Conflict Resolution – TechnoServe in-house Training.</li><li>Negotiating Skills and other Managerial Training programs at TechnoServe</li><li>Management of Credit Union by the Credit Union Association of Ghana.</li></ul></p><p><br></p><p><strong>OTHER ACTIVITIES</strong></p><p>Ordained Minister, Methodist Church Ghana</p><p>Board Chairman – Farmapine Ghana Ltd 2003-2006</p><p>Until December 2007, National Treasurer, Scripture Union Ghana</p><p><br></p><p><strong>WORKING EXPERIENCE</strong></p><p>The Honorary Treasurer has over fifty years of experience working in the Financial Sector.</p><p>Before joining the Church\'s Finance Team, the Very Rev. Anthony Kwamena Cobbah was the Deputy Country Director, Finance and Administration of TechnoServe Incorporated (Ghana), an American Private Voluntary Organisation. He also worked as an assistant accountant at Agricare Ltd, a subsidiary of the Pfizer Group of Companies. Accountant at Cotton Production Company Ltd., funded by the African Development Bank, and worked with the Grains and Legumes Development Board. Since joining the Finance Directorate of the Methodist Church Ghana, the Honorary Treasurer has impacted the Church\'s Finance and Development Policies, leading to dramatic changes in the payment of stipends to Ministerial Staff and the physical development of the Church\'s assets.</p><p><br></p>','/uploads/speakers/1786092199550-5277d3703cda.jpg',0,0,'2026-08-07 08:43:20','2026-08-07 08:43:20'),(45,'REVD DR. MARTIN MUJINGA','GENERAL SECRETARY ','AFRICA METHODIST COUNCIL','ZIMBABWE','Is the General Secretary of the Africa Methodist Council. He is an Ordained Minister of the Methodist Church in Zimbabwe (MCZ). Before this appointment, he was the General Secretary of the MCZ, a position he held while serving as the Academic Dean at United Theological College. He holds a PhD in African Theology from the University of KwaZulu-Natal. His MA, BA Hons and Diploma in Religious Studies were obtained from the University of Zimbabwe. He also diversified into Human Resources, where he holds a Diploma from the Institute of People Management in Zimbabwe.&nbsp;<p>Dr Mujinga served in different capacities in the Church and in academic institutions. He was recognised by the University of Wesley, Ondo, Nigeria, to supervise two of its PhD Candidates. He is also an external examiner for the University of KwaZulu-Natal, University of South Africa, University of Johannesburg, and University of Pretoria. He was honoured by the University of North West in South Africa to be an External Expert Reviewer of the Undergraduate Curriculum.&nbsp;</p><p>Dr Mujinga taught at various institutions in Zimbabwe and South Africa. He is a distinguished National Research Foundation (NRF) rated Scholar. Dr Mujinga is a Research Fellow/Associate in the Research Institute of Theology and Religion at the University of South Africa and in the Department of Theology and Ecclesiology at Stellenbosch University, in Cape Town, South Africa. He has 65 publications, including books, book chapters, peer-reviewed journal articles, and conference proceedings in his name. Dr Mujinga is a peer reviewer of more than ten International Journals,&nbsp;</p><p>&nbsp;He has presented at several academic and ecumenical platforms in Africa, Asia, and Europe, including the Irish Conference and London Synod. Dr Mujinga also trained as a regional Election Observation and Analysis, conducted by the All Africa Conference of Churches in collaboration with the African Union Commission and the Kofi Annan International Peacekeeping Training. Dr Mujinga also serves as the Co-Secretary of the Anglican Methodist International Coordinating Committee, a member of the World Mission Fund and the Chairperson of the Reparatory Justice Dialogue of the British Conference and her partner churches in West Africa.&nbsp;</p><p>He is married to Revd Meloreen Mujinga, a Counsellor by profession, and they are blessed with three children, Chikomborero, Ropafadzo and Nyasha.&nbsp;</p><p><br></p>','/uploads/speakers/1786092277244-a110ac552b6e.jpg',0,0,'2026-08-07 08:44:38','2026-08-07 08:44:38'),(46,'MOST REVD DR PAUL K. BOAFO','AFRICA METHODIST COUNCIL PRESIDENT','AFRICA METHODIST COUNCIL','GHANA','In March 2023, the Most Rev Dr Paul Kwabena Boafo was elected as the second President of the Africa Methodist Council at the second Quadrennial Conference, held in Cotonou, Benin, from 7-12 March 2023. He took over from Bishop Joseph Mwaine Ntombura, retired Presiding Bishop of the Methodist Church in Kenya. The Most Rev Dr Boafo is a Ghanaian theologian, minister and the Immediate Past Presiding Bishop of the Methodist Church Ghana.<p>In 1963, Boafo enrolled as a pupil at the Asankrangwa Roman Catholic Primary School. After his first year in elementary school, he moved to live with his maternal uncle, Reverend John Bennet Nsowah Quasie, then a catechist of the Methodist Church at Ankonsia, near Bawdie in the Western Region. Boafo\'s uncle was posted to Wa in the Upper West Region after completing his catechist training at the Freeman College in Kumasi. Boafo then went to the Wa Experimental Primary School and later transferred to other schools in Mangu, Kenyasi, Sefwi Wiawso, and Sefwi-Bekwai due to his uncle\'s work as a travelling minister. After passing the common entrance examination at the Sefwi Bekwai Methodist Middle School, Boafo was enrolled at the Wenchi Methodist Secondary School from 1972 to 1977, where he obtained his GCE \'O\' Level. He went on to Wesley College, Kumasi, where he trained as a teacher from 1978 to 1981. He was awarded the Men\'s Prize in 1981 upon completing his tenure as the Men\'s Secretary. Between 1989 and 1992, he studied for a bachelor\'s degree in philosophy and the Study of Religions at the University of Ghana, Legon. In 1996, he was awarded a World Church Office Scholarship for his Master of Theology Degree (MTh) at Queen\'s University, Belfast. Upon the recommendation of the scholarship\'s sponsors, the Methodist Church in Ireland and the Methodist Church Ghana, he pursued a doctorate in Wesleyan Studies from the same institution. He received a PhD in 1999.</p><p><br></p><p><strong>CAREER </strong>-Paul Boafo was a pupil teacher at the St. Peter and Paul Anglican Primary School in Saltpond, Central Region, Ghana, in 1977. In his early career, he taught at the Mpasatia Methodist Primary School. Initially a lay preacher, Boafo was commissioned a probationer on June 8 1986, at the Wesley Cathedral in Accra and subsequently ordained a full Methodist. He previously served as the Administrative Bishop of the Church. He is the first ordained minister to serve in both capacities in the episcopal history of the Ghanaian Methodist Church. Boafo also served as the Protestant Chaplain of the Kwame Nkrumah University of Science and Technology (KNUST).&nbsp;</p><p><br></p><p><strong>EARLY LIFE AND EDUCATION </strong>-An ethnic Fante, Paul Kwabena Boafo was born in Asankragua, in the Western Region of Ghana, to Roman Catholic parents, Opanin Paul Kwaw Boafo and Agatha Ama Asamoah Boafo. His mother described him as a sickly child. By the age of three, he was a frequent patient at the local Catholic hospital.&nbsp;</p><p><br></p>','/uploads/speakers/1786092362568-2cea830a9b3a.jpg',0,0,'2026-08-07 08:46:04','2026-08-07 08:46:04');
